#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

int main(int argc, char **argv)
{
    /* No argument supplied */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Convert the argument to a number */
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad conversion (no digits or extra characters) */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Out‑of‑range check (the original program limits to 1 000 000 000) */
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Numbers smaller than 2 have no prime factors */
    if (n < 2) {
        puts("NONE");
        return 0;
    }

    /* Prime factorisation */
    bool first = true;          /* true for the first printed factor */
    long remaining = n;         /* value that is reduced as factors are removed */

    for (long p = 2; p * p <= remaining; ++p) {
        if (remaining % p == 0) {
            int exp = 0;
            while (remaining % p == 0) {
                remaining /= p;
                ++exp;
            }
            if (!first) putchar(' ');
            printf("%ld^%d", p, exp);
            first = false;
        }
    }

    /* If something is left, it is a prime > sqrt(original) */
    if (remaining > 1) {
        if (!first) putchar(' ');
        printf("%ld^1", remaining);
    }

    putchar('\n');
    return 0;
}
